<header class="page-header"><div><p class="eyebrow">Active campaign</p><h1>Prospects</h1><p>Campaign-specific relationships, research, and pipeline status.</p></div><a class="button" href="<?= $escape($newUrl) ?>">New prospect</a></header>
<nav class="tab-list"><a href="<?= $escape($activeUrl) ?>"<?= !$archived?' aria-current="page"':'' ?>>Active</a><a href="<?= $escape($archivedUrl) ?>"<?= $archived?' aria-current="page"':'' ?>>Archived</a></nav>
<form class="filter-bar" method="get" action="<?= $escape($indexUrl) ?>"><?php if($archived): ?><input type="hidden" name="archived" value="1"><?php endif; ?><label>Search<input name="q" value="<?= $escape($filters['q']) ?>"></label><label>Segment<select name="segment"><option value="">All segments</option><?php foreach($segments as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['segment']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['status']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Sort<select name="sort"><?php foreach(['updated'=>'Recently updated','name'=>'Name','status'=>'Status'] as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['sort']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Direction<select name="direction"><option value="desc"<?= $filters['direction']==='desc'?' selected':'' ?>>Descending</option><option value="asc"<?= $filters['direction']==='asc'?' selected':'' ?>>Ascending</option></select></label><button>Apply</button><a href="<?= $escape($archived?$archivedUrl:$activeUrl) ?>">Clear</a></form>
<p><?= $escape($count) ?> result<?= $count===1?'':'s' ?>.</p><?php if($prospects===[]): ?><section class="empty-state"><h2><?= $count===0&&($filters['q']!==''||$filters['segment']!==''||$filters['status']!=='')?'No matching prospects':'No '.($archived?'archived':'active').' prospects' ?></h2><p>Add a company, person, or company/contact relationship to the campaign.</p></section><?php else: ?><div class="table-scroll"><table><thead><tr><th>Prospect</th><th>Segment</th><th>Status</th><th>Why them</th></tr></thead><tbody><?php foreach($prospects as $p): ?><tr><th><a href="<?= $escape($showUrl((int)$p['id'])) ?>"><?= $escape($p['company_name']?:trim(($p['first_name']??'').' '.($p['last_name']??''))) ?></a></th><td><?= $escape($segments[$p['segment']]??$p['segment']) ?></td><td><?= $escape($statuses[$p['status']]??$p['status']) ?></td><td><?= $escape($p['why_them']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($pages>1): ?><nav class="pagination" aria-label="Prospect pages"><?php for($number=1;$number<=$pages;$number++): ?><a href="<?= $escape($indexUrl.'?'.http_build_query($filters+['page'=>$number])) ?>"<?= $number===$page?' aria-current="page"':'' ?>><?= $escape($number) ?></a><?php endfor; ?></nav><?php endif; ?>
